// /api/upgrade-sign/tx: signing path (preview, or thespicemelange.org/sign/ when WALLET_PAGES_LIVE=1) for Sajan's mainnet collection upgrade (Siona SU5/SU8, 10/10 PT).
// The server serves ONE exact unsigned transaction (store-core/upgrade-tx.json, generated by spice-license/rebuild_upgrade_tx.py)
// and only if (1) the preview switches are on, (2) sha256(bytes) is listed in UPGRADE_REVIEWED_SHA256 (set only after review), and
// (3) the decoded bytes are exactly the reviewed SHAPE: sender/gas owner = Sajan's address, inputs = his UpgradeCap, commands =
// authorize_upgrade -> Upgrade(package 0xef77...dffdd) -> commit_upgrade, budget <= 0.06 SUI, no expiration games.
// The wallet signs AND executes those bytes itself (sui:signAndExecuteTransaction). The server never receives a signature and never
// relays a transaction (no sign-then-server-submit path, Sajan/Siona 10:30 PM PT). Never signs anything.
import { bcs } from '@mysten/sui/bcs';
import { TransactionDataBuilder } from '@mysten/sui/transactions';
import TX from './upgrade-tx.json' with { type: 'json' };
import { signRateLimit } from './sign-ratelimit.js';

// Reviewed constants (NOT read from upgrade-tx.json, so a regenerated file can't move them).
export const EXPECT = Object.freeze({
  sender: '0x04b178f7855b2e84ae9c1585093009bb6c212cd3b5ccf9c76672dda04be087e0',
  upgradeCap: '0xbb3fa6c6e8cefe048132d099b60a8d657f8292c9c469af10dff157011b4e964b',
  package: '0xef77702f895c8d3131a3579931d3f48eb8b2b98b95ea8446fba342b565bdffdd',
  maxBudget: 60_000_000n,
  graphql: 'https://graphql.mainnet.sui.io/graphql',
});
const json = (status, body) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', 'referrer-policy': 'no-referrer' } });
const hex = (u8) => [...u8].map((b) => b.toString(16).padStart(2, '0')).join('');
export const sha256Hex = async (u8) => hex(new Uint8Array(await crypto.subtle.digest('SHA-256', u8)));
const b64ToU8 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
export const reviewedList = (env) => String(env?.UPGRADE_REVIEWED_SHA256 ?? '').split(/[\s,]+/).filter((h) => /^[0-9a-f]{64}$/.test(h));
export const enabled = (env) => (env?.SPICE_CERT_PREVIEW === '1' || env?.WALLET_PAGES_LIVE === '1') && env?.UPGRADE_SIGN_ENABLED === '1';

// Throws unless the bytes are exactly the reviewed shape. Returns a plain summary for the page.
export function checkShape(u8) {
  const t = bcs.TransactionData.parse(u8);
  const v = t.V1; if (!v) throw new Error('not TransactionData V1');
  const fail = (m) => { throw new Error(m); };
  if (v.sender !== EXPECT.sender) fail('sender is not Sajan\'s UpgradeCap address');
  if (v.gasData.owner !== EXPECT.sender) fail('gas owner is not the sender');
  if (BigInt(v.gasData.budget) > EXPECT.maxBudget) fail('gas budget above 0.06 SUI');
  if (v.expiration?.$kind && v.expiration.$kind !== 'None') fail('unexpected expiration');
  const p = v.kind.ProgrammableTransaction; if (!p) fail('not a programmable transaction');
  const objs = p.inputs.filter((i) => i.$kind === 'Object');
  if (objs.length !== 1 || objs[0].Object.ImmOrOwnedObject?.objectId !== EXPECT.upgradeCap) fail('object inputs must be exactly the UpgradeCap');
  const c = p.commands;
  const mc = (x, fn) => x?.$kind === 'MoveCall' && x.MoveCall.package === '0x' + '0'.repeat(63) + '2' && x.MoveCall.module === 'package' && x.MoveCall.function === fn;
  if (c.length !== 3 || !mc(c[0], 'authorize_upgrade') || c[1]?.$kind !== 'Upgrade' || !mc(c[2], 'commit_upgrade')) fail('commands must be authorize_upgrade, Upgrade, commit_upgrade');
  if (c[1].Upgrade.package !== EXPECT.package) fail('Upgrade targets another package');
  return { txDigest: TransactionDataBuilder.getDigestFromBytes(u8), sender: v.sender, upgradeCap: EXPECT.upgradeCap, package: EXPECT.package, modules: c[1].Upgrade.modules.length,
    gasBudgetSui: Number(v.gasData.budget) / 1e9, gasPriceMist: String(v.gasData.price), gasCoins: v.gasData.payment.map((g) => g.objectId) };
}

async function served(env) {
  const u8 = b64ToU8(TX.txBytesB64); const sha = await sha256Hex(u8);
  if (!reviewedList(env).includes(sha)) return { err: json(409, { ok: false, reason: 'not_reviewed', sha256: sha }) };
  let summary; try { summary = checkShape(u8); } catch (e) { return { err: json(409, { ok: false, reason: 'bad_shape', detail: String(e.message) }) }; }
  return { u8, sha, summary };
}
async function gql(fetchImpl, query, variables) {
  const r = await fetchImpl(EXPECT.graphql, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ query, variables }) });
  return r.json();
}
export async function handleUpgradeSign(action, { request, env }, fetchImpl = fetch, deps = {}) {
  if (!enabled(env)) return json(404, { ok: false, reason: 'not_found' });
  if (env?.SPICE_CERT_PREVIEW !== '1') { const lim = await (deps.rateLimit ?? signRateLimit)(request, env, Date.now(), 'upgrade-sign/' + action); if (lim) return lim; } // F-2 (prod domain)
  const s = await served(env); if (s.err) return s.err;
  if (action === 'tx' && request.method === 'GET') {
    // Re-simulate now so a stale gas coin (any tx from the sender) is caught before Sajan signs.
    const sim = await gql(fetchImpl, 'query($t: JSON!){ simulateTransaction(transaction:$t){ effects{ status executionError{ message } } } }', { t: { bcs: { value: TX.txBytesB64 } } }).catch(() => null);
    const st = sim?.data?.simulateTransaction?.effects;
    return json(200, { ok: true, txBytesB64: TX.txBytesB64, sha256: s.sha, builtAt: TX.builtAt, simulatedNetSui: TX.simulatedNetSui, summary: s.summary,
      simulation: st ? { status: st.status, error: st.executionError?.message ?? null } : { status: 'UNKNOWN' } });
  }
  return json(405, { ok: false, reason: 'method' });
}
